package com.demo.agentfw.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * One chat message. {@code sessionId} is generated by the browser tab (one chat per tab). A
 * {@code fileId} is an attachment: the message is then an instruction about that file and the file
 * agent is called by a code rule.
 */
public record ChatRequest(
        @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.:-]+",
                message = "sessionId may only contain letters, digits and _ . : -") String sessionId,
        @Size(max = 4000) String message,
        @Pattern(regexp = "[0-9a-fA-F-]{36}", message = "fileId is not a file id") String fileId) {

    static final String DEFAULT_FILE_INSTRUCTION = "Summarize this file.";

    /** The text to process: the message, or a default instruction for an attachment sent without text. */
    public String effectiveMessage() {
        boolean blank = message == null || message.isBlank();
        if (blank) {
            if (fileId == null || fileId.isBlank()) {
                throw new IllegalArgumentException("message is required");
            }
            return DEFAULT_FILE_INSTRUCTION;
        }
        return message.strip();
    }
}
